        current: "https://a.example/x", next: "http://a.example/y")
        == "Refusing to replay request body across HTTPS->HTTP redirect: "
        + "https://a.example/x -> http://a.example/y")
  }

  /* A caller-supplied session keeps the SDK's redirect rules: they are
     attached to each task, so the guard is not lost with the session's own
     delegate. */
  @Test func testBhvLangswift037SuppliedSessionStillAppliesTheRedirectRules() throws {
    let session = UnitStubURLProtocol.session { _ in (Data("{}".utf8), 200, [:]) }
    let supplied = try TransportOptionsBuilder().session(session).build()
    let client = try DefaultApiClient(transportOptions: supplied)
    #expect(client.appliesRedirectRules)
    client.close()
  }

  /* A minimal custom transport that does not implement close() is still
   * closable: the protocol extension supplies a no-op. */
  @Test func testBhvLifecycle038CloseHasANoOpDefaultForAMinimalTransport() {
    struct MinimalClient: ApiClient {
      func sendRequest(
        method: String, url: String, headers: [String: String], body: Any?
      ) async throws -> ApiHttpResponse {
        return ApiHttpResponse(statusCode: 204, body: "", headers: [:])
      }
    }
    let client: any ApiClient = MinimalClient()
    client.close()
