  }

  /* D29: a request after close() is a wrong call order, with one text. */
  @Test func testBhvLifecycle023SendAfterCloseThrowsTheCanonicalInvalidState() async throws {
    let client = makeClient { _ in (self.body(), 200, [:]) }
    client.close()
    let error = await #expect(throws: ConfigurationError.self) {
      _ = try await client.sendRequest(
        method: "GET", url: "https://example.com", headers: [:], body: nil)
    }
    #expect(
      error
        == ConfigurationError.invalidState(
          "ApiClient has been closed and can no longer send requests"))
  }

  /* F1078: close() is graceful. A request already in flight finishes, the
     transport the SDK built is released only when it has, and a request made
     meanwhile fails with the one canonical error. */
  @Test func testBhvLifecycle021CloseLetsARequestInFlightFinishAndThenReleasesTheTransport()
    async throws
  {
    let gate = CloseGate()
    let client = makeClient { _ in
      gate.holdRequest()
      return (Data("{}".utf8), 200, [:])
    }
    let inFlight = Task {
      try await client.sendRequest(
        method: "GET", url: "https://example.com/slow", headers: [:], body: nil)
    }
    try await gate.waitUntilHeld()

    client.close()

    #expect(client.isClosed)
    #expect(!client.isTransportReleased)
    let error = await #expect(throws: ConfigurationError.self) {
      _ = try await client.sendRequest(
        method: "GET", url: "https://example.com/next", headers: [:], body: nil)
    }
    #expect(error == DefaultApiClient.closedError)

    gate.release()
    let response = try await inFlight.value
    #expect(response.statusCode == 200)
    #expect(client.isTransportReleased)
  }

  /* A retry of a request that was already in flight when close() came is part
     of that request, so it still goes out. */
  @Test func testBhvLifecycle019CloseLetsTheRetriesOfARequestInFlightFinish() async throws {
    let gate = CloseGate()
    let calls = CallCounter()
    let client = makeClient { _ in
      if calls.next() == 1 {
        gate.holdRequest()
        return (Data("{}".utf8), 503, ["Retry-After": "0"])
      }
      return (Data("{}".utf8), 200, [:])
    }
    let inFlight = Task {
      try await client.sendRequest(
        method: "GET", url: "https://example.com/flaky", headers: [:], body: nil)
    }
    try await gate.waitUntilHeld()

    client.close()
    gate.release()

    let response = try await inFlight.value
    #expect(response.statusCode == 200)
    #expect(calls.count == 2)
    #expect(client.isTransportReleased)
  }

  /* Closing an idle client releases the transport at once, and a second close
     changes nothing. */
  @Test func testBhvLifecycle022CloseOfAnIdleClientReleasesAtOnceAndASecondCloseIsANoOp()
    async throws
  {
    let client = makeClient { _ in (self.body(), 200, [:]) }
    _ = try await client.sendRequest(
      method: "GET", url: "https://example.com/once", headers: [:], body: nil)

    client.close()
    #expect(client.isClosed)
    #expect(client.isTransportReleased)

    client.close()
    #expect(client.isClosed)
    #expect(client.isTransportReleased)
    await #expect(throws: ConfigurationError.self) {
      _ = try await client.sendRequest(
        method: "GET", url: "https://example.com/twice", headers: [:], body: nil)
    }
  }

  /* A session the caller supplied is never released by close(), and keeps
     working afterwards. */
  @Test func testBhvLifecycle020CloseNeverReleasesACallerSuppliedSession() async throws {
    let probe = SessionInvalidationProbe()
    let configuration = URLSessionConfiguration.ephemeral
    configuration.protocolClasses = [UnitStubURLProtocol.self]
    let session = URLSession(configuration: configuration, delegate: probe, delegateQueue: nil)
    UnitStubURLProtocol.handler = { _ in (Data("{}".utf8), 200, [:]) }
    let supplied = try TransportOptionsBuilder().session(session).build()
    let client = try DefaultApiClient(transportOptions: supplied)
    _ = try await client.sendRequest(
      method: "GET", url: "https://example.com/mine", headers: [:], body: nil)

    client.close()
    client.close()
    try await Task.sleep(nanoseconds: 200_000_000)

    #expect(client.isClosed)
    #expect(!client.isTransportReleased)
    #expect(!probe.invalidated)
    session.invalidateAndCancel()
  }

  /* The token request goes to another origin, so the caller's default
     headers stay off it; its own headers and the User-Agent still go. */
  /* The token endpoint request (a noRedirect POST) never carries the transport default headers. */
  @Test func testBhvAuth010TokenEndpointRequestCarriesNoDefaultHeaders() async throws {
    var seen: [URLRequest] = []
    let transport = try TransportOptionsBuilder()
      .defaultHeader(name: "X-Api-Secret", value: "api-only")
      .userAgent("Agent/1.0")
      .build()
    let client = makeClient(transport: transport) { request in
      seen.append(request)
      return (self.body(), 200, [:])
    }
    _ = try await client.sendRequest(
      method: "POST", url: "https://idp.example.com/token", headers: ["Accept": "application/json"],
      body: Data("a=b".utf8), noRedirect: true)
    _ = try await client.sendRequest(
      method: "GET", url: "https://api.example.com/items", headers: [:], body: nil)

    #expect(seen.count == 2)
    #expect(seen[0].value(forHTTPHeaderField: "X-Api-Secret") == nil)
    #expect(seen[0].value(forHTTPHeaderField: "Accept") == "application/json")
    #expect(seen[0].value(forHTTPHeaderField: "User-Agent") == "Agent/1.0")
    #expect(seen[1].value(forHTTPHeaderField: "X-Api-Secret") == "api-only")
  }

