    await #expect(throws: ApiError.self) {
      _ = try await api.getInventory(options: GetInventoryOptions(maxRetries: 1))
    }
    #expect(calls == 2)
  }

  /* With no retry setting, the pauses between attempts are half a second, then one second. */
  @Test func testBhvMisc168TheDefaultPausesBetweenAttemptsAreHalfASecondThenOneSecond() {
    #expect(DefaultApiClient.retryDelay(attempt: 0, retryAfter: nil, jitter: 0) == 0.5)
    #expect(DefaultApiClient.retryDelay(attempt: 1, retryAfter: nil, jitter: 0) == 1.0)
  }

  /* The pause between retries starts at half a second, doubles on each attempt, and never exceeds eight seconds. */
  @Test func testBhvMisc169TheRetryPauseDoublesFromHalfASecondAndNeverExceedsEight() {
    #expect(DefaultApiClient.retryDelay(attempt: 0, retryAfter: nil, jitter: 0) == 0.5)
    #expect(DefaultApiClient.retryDelay(attempt: 2, retryAfter: nil, jitter: 0) == 2.0)
    #expect(DefaultApiClient.retryDelay(attempt: 20, retryAfter: nil, jitter: 0) == 8.0)
  }

  /* A per-call maximum retry count larger than the transport limit applies to that call and allows more attempts. */
  @Test func testBhvMisc171APerCallRetryCountAboveTheTransportLimitAllowsMoreAttempts() async throws
  {
    var calls = 0
    let client = makeClient(
      transport: try TransportOptionsBuilder().maxRetries(0).build(),
      handler: { _ in
        calls += 1
        return (self.body(), 503, ["Retry-After": "0"])
      })
    let api = StoreApi(
      apiClient: client, config: ConfigurationBuilder().baseURL("http://localhost").build())
    await #expect(throws: ApiError.self) {
      _ = try await api.getInventory(options: GetInventoryOptions(maxRetries: 2))
    }
    #expect(calls == 3)
  }

  /* A streamed body crossing from HTTPS to HTTP is replayed only when the original body was empty, and a missing original is refused. */
  @Test func testBhvMisc173AStreamedBodyCrossingHttpsToHttpNeedsAnEmptyOriginal() throws {
    var streamed = URLRequest(url: try #require(URL(string: "http://other.example/x")))
    streamed.httpBodyStream = InputStream(data: Data())
    #expect(
      !DefaultApiClient.refusesBodyReplay(
        currentScheme: "https", nextScheme: "http", request: streamed, originalBody: Data()))
    #expect(
      DefaultApiClient.refusesBodyReplay(
        currentScheme: "https", nextScheme: "http", request: streamed, originalBody: nil))
  }

  /* A header value refused for a line break is never repeated in the error raised for it. */
  @Test func testBhvMisc174ARefusedHeaderValueIsNotRepeatedInTheError() async throws {
    let client = makeClient { _ in (self.body(), 200, [:]) }
    do {
      _ = try await client.sendRequest(
        method: "GET", url: "https://example.com/x",
        headers: ["X-Secret": "top\nsecret-value"], body: nil, noRedirect: false)
      Issue.record("A header value holding a line break must be refused")
    } catch {
      #expect(!"\(error)".contains("secret-value"))
      #expect(!error.localizedDescription.contains("secret-value"))
    }
  }

  /* Credential-bearing header names are recognised regardless of letter case, and ordinary header names are not. */
  @Test func testBhvMisc175CredentialHeaderNamesAreRecognisedInAnyCase() {
    #expect(DefaultApiClient.isSensitiveRedirectHeader("AUTHORIZATION"))
    #expect(DefaultApiClient.isSensitiveRedirectHeader("X-Api-KEY"))
    #expect(!DefaultApiClient.isSensitiveRedirectHeader("Content-Type"))
  }

  #if !os(Linux)
    /* A request body is replayed across a 307 redirect that keeps the same plain-text scheme. */
    @Test func testBhvMisc165ABodyIsReplayedAcrossAHttpToHttpRedirect() async throws {
      var calls = 0
      let client = makeClient(
        transport: try TransportOptionsBuilder().followRedirects(true).build(),
        handler: { _ in
          calls += 1
          if calls == 1 {
            return (self.body(), 307, ["Location": "http://example.com/next"])
          }
          return (self.body(), 200, [:])
        })
      let resp = try await client.sendRequest(
        method: "POST", url: "http://example.com/start",
        headers: ["Content-Type": "application/json"],
        body: Data("{\"a\":1}".utf8), noRedirect: false)
      #expect(resp.statusCode == 200)
      #expect(calls == 2)
    }
  #endif

  /* A default Content-Type header given in any letter case is not sent when the request has no body. */
  @Test func testBhvMisc177ADefaultContentTypeInAnyCaseIsNotSentWithoutABody() async throws {
    var seen: URLRequest?
    let transport = try TransportOptionsBuilder().defaultHeader(
      name: "content-TYPE", value: "application/json"
    ).build()
    let client = makeClient(
      transport: transport,
      handler: { request in
        seen = request
        return (self.body(), 200, [:])
      })
    _ = try await client.sendRequest(
      method: "GET", url: "https://example.com/test", headers: [:], body: nil, noRedirect: false)
    #expect(seen?.value(forHTTPHeaderField: "Content-Type") == nil)
  }

  /* Content placed in a header is sent exactly as serialised, with no percent-encoding applied. */
  @Test func testBhvMisc181AHeaderValueIsSentExactlyAsSerialised() async throws {
    var seen: URLRequest?
    let client = makeClient { request in
      seen = request
      return (self.body(), 200, [:])
    }
    _ = try await client.sendRequest(
      method: "GET", url: "https://example.com/test",
      headers: ["X-Raw": "a b%20c/d"], body: nil, noRedirect: false)
    #expect(seen?.value(forHTTPHeaderField: "X-Raw") == "a b%20c/d")
  }

  #if !os(Linux)
    /* Removing a credential header on a cross-origin hop matches its name without regard to letter case. */
    @Test func testBhvMisc182ACredentialHeaderIsRemovedOnACrossOriginHopWhateverItsCase()
      async throws
    {
      var seen: [URLRequest] = []
      let client = makeClient(
        transport: try TransportOptionsBuilder().followRedirects(true).build(),
        handler: { request in
          seen.append(request)
          if seen.count == 1 {
            return (self.body(), 302, ["Location": "https://other.example.com/end"])
          }
          return (self.body(), 200, [:])
        })
      _ = try await client.sendRequest(
        method: "GET", url: "https://example.com/start",
        headers: ["authorization": "Bearer t"], body: nil, noRedirect: false)
      #expect(seen[0].value(forHTTPHeaderField: "authorization") == "Bearer t")
      #expect(seen[1].value(forHTTPHeaderField: "Authorization") == nil)
    }
  #endif

  /* A client reports itself as closed only after close has been called on it. */
  @Test func testBhvMisc188AClientReportsClosedOnlyAfterClose() {
    let client = makeClient { _ in (self.body(), 200, [:]) }
    #expect(!client.isClosed)
    client.close()
    #expect(client.isClosed)
  }

  /* Calling close on a client that is already closed does nothing and raises no error. */
  @Test func testBhvMisc203ClosingAnAlreadyClosedClientDoesNothing() {
    let client = makeClient { _ in (self.body(), 200, [:]) }
    client.close()
    client.close()
    #expect(client.isClosed)
  }

  /* A 404 or 500 response from a call raises the corresponding error through the API layer. */
  @Test(arguments: [404, 500]) func testBhvMisc212A404Or500RaisesAnApiError(status: Int)
    async throws
  {
    let client = makeClient { _ in (self.body("{}"), status, [:]) }
    let api = StoreApi(
      apiClient: client, config: ConfigurationBuilder().baseURL("http://localhost").build())
    await #expect(throws: ApiError.self) {
      _ = try await api.getInventory()
    }
  }

  /* When the connection drops before any response arrives, a POST or PATCH is sent exactly once, and QUERY is treated as an idempotent method. */
  @Test func testBhvMisc161ADroppedConnectionSendsANonIdempotentRequestOnceAndAQueryAgain()
    async throws
  {
    for method in ["POST", "PATCH"] {
      var calls = 0
      let client = makeClient(
        transport: try TransportOptionsBuilder().build(),
        handler: { _ in
          calls += 1
          return (self.body(), 200, ["X-Stub-Fail-Before-Response": "cannotConnectToHost"])
        })
      _ = await #expect(throws: NetworkError.self) {
        _ = try await client.sendRequest(
          method: method, url: "https://example.com/write", headers: [:], body: nil,
          noRedirect: false)
      }
      #expect(calls == 1)
    }
    var calls = 0
    let client = makeClient(
      transport: try TransportOptionsBuilder().build(),
      handler: { _ in
        calls += 1
        if calls == 1 {
          return (self.body(), 200, ["X-Stub-Fail-Before-Response": "cannotConnectToHost"])
        }
        return (self.body(), 200, [:])
      })
    _ = try await client.sendRequest(
      method: "QUERY", url: "https://example.com/search", headers: [:], body: nil, noRedirect: false
    )
    #expect(calls == 2)
  }

  /* A TLS or certificate failure is reported as a network error on the first attempt and is never retried. */
  @Test func testBhvMisc170ATlsFailureIsReportedOnceAndNeverRetried() async throws {
    var calls = 0
    let client = makeClient(
      transport: try TransportOptionsBuilder().build(),
      handler: { _ in
        calls += 1
        return (self.body(), 200, ["X-Stub-Fail-Before-Response": "secureConnectionFailed"])
      })
    let error = await #expect(throws: NetworkError.self) {
      _ = try await client.sendRequest(
        method: "GET", url: "https://example.com/secure", headers: [:], body: nil, noRedirect: false
      )
    }
    #expect(calls == 1)
    #expect((error?.underlyingError as? URLError)?.code == .secureConnectionFailed)
  }

  /* Closing a client returns without waiting for a request that is still running and does not cancel it. */
  @Test func testBhvMisc184CloseDoesNotWaitForOrCancelARunningRequest() async throws {
    let entered = DispatchSemaphore(value: 0)
    let release = DispatchSemaphore(value: 0)
    let client = makeClient(
      transport: try TransportOptionsBuilder().build(),
      handler: { _ in
        entered.signal()
        release.wait()
        return (self.body(), 200, [:])
      })
    let running = Task {
      try await client.sendRequest(
        method: "GET", url: "https://example.com/slow", headers: [:], body: nil, noRedirect: false)
    }
    await Task.detached { entered.wait() }.value
    client.close()
    release.signal()
    let response = try await running.value
    #expect(response.statusCode == 200)
  }

  /* A missing CA certificate file is rejected even when certificate verification is disabled, and the error names the file. */
  @Test func testBhvMisc270AMissingCaCertificateFileIsRejectedEvenWithVerificationOff() throws {
    let transport = try TransportOptionsBuilder()
      .verifySsl(false).caCertPath("/nonexistent/ca.pem").build()
    let error = #expect(throws: ConfigurationError.self) {
      _ = try DefaultApiClient(transportOptions: transport)
    }
    guard case .invalidCACertificate(let message)? = error else {
      Issue.record("expected invalidCACertificate, got \(String(describing: error))")
      return
    }
    #expect(message.contains("/nonexistent/ca.pem"))
  }
}

// MARK: - Model-part stand-in for multipart unit tests

/// A Codable stand-in for a generated model used as a multipart part. Its
/// stored properties carry camelCase WIRE names, exactly as generated models
/// do, so the multipart model-part branch can be exercised without referring
/// to any model that happens to exist in the spec being generated.
private struct MultipartModelPartFixture: Codable {
  let isEnabled: Bool
  let recordedAt: Date
}

/// A string enum standing in for a generated enum in the multipart tests.
private enum MultipartEnumFixture: String, Codable {
  case crimson = "crimson-red"
}

private final class CloseGate: @unchecked Sendable {
  private let lock = NSLock()
  private var flag = false
  private let proceed = DispatchSemaphore(value: 0)

  /// Called by the stub when the request has reached it; blocks until `release()`.
  func holdRequest() {
    lock.lock()
    flag = true
    lock.unlock()
    proceed.wait()
  }

  /// Lets the held request go on.
  func release() {
    proceed.signal()
  }

  /// Waits, without blocking a thread, until the stub holds the request.
  func waitUntilHeld() async throws {
    for _ in 0..<500 {
      lock.lock()
      let held = flag
      lock.unlock()
      if held { return }
      try await Task.sleep(nanoseconds: 10_000_000)
    }
    throw ConfigurationError.invalidState("the request never reached the stub")
  }
}

/// Counts the requests a stub has answered.
private final class CallCounter: @unchecked Sendable {
  private let lock = NSLock()
  private var calls = 0

  /// Counts one more call and returns its number, starting at 1.
  func next() -> Int {
    lock.lock()
    defer { lock.unlock() }
    calls += 1
    return calls
  }

  var count: Int {
    lock.lock()
    defer { lock.unlock() }
    return calls
  }
}

/// Records whether a session was invalidated.
private final class SessionInvalidationProbe: NSObject, URLSessionDelegate, @unchecked Sendable {
  private let lock = NSLock()
  private var flag = false

  var invalidated: Bool {
    lock.lock()
    defer { lock.unlock() }
    return flag
  }

  func urlSession(_ session: URLSession, didBecomeInvalidWithError error: Error?) {
    lock.lock()
    flag = true
    lock.unlock()
  }
}

// MARK: - URL Protocol stub for unit tests

/* Never answers a request, and counts how often the loader stops it, so a test can see a cancelled call reach the transport. */
private final class StallingURLProtocol: URLProtocol {
  nonisolated(unsafe) static var stopCount = 0

  override class func canInit(with request: URLRequest) -> Bool { return true }
  override class func canonicalRequest(for request: URLRequest) -> URLRequest { return request }
  override func startLoading() {}
  override func stopLoading() {
    StallingURLProtocol.stopCount += 1
  }
}

private final class UnitStubURLProtocol: URLProtocol {
  nonisolated(unsafe) static var handler: ((URLRequest) -> (Data, Int, [String: String]))?
  /// A response header naming a URLError code makes the stub fail the load
  /// with that error after the response is delivered.
  static let failWithHeader = "X-Stub-Fail-With"
  /// A response header naming a URLError code makes the stub fail the load
  /// before any response arrives (a connect deadline or a refused connection).
  static let failBeforeResponseHeader = "X-Stub-Fail-Before-Response"

  static func session(handler: @escaping (URLRequest) -> (Data, Int, [String: String]))
    -> URLSession
  {
    self.handler = handler
    let config = URLSessionConfiguration.ephemeral
    config.protocolClasses = [UnitStubURLProtocol.self]
    return URLSession(configuration: config)
  }

  override class func canInit(with request: URLRequest) -> Bool { return true }
  override class func canonicalRequest(for request: URLRequest) -> URLRequest { return request }

  /// URLSession hands a protocol the body as `httpBodyStream`, not
  /// `httpBody`; read it back so handlers can inspect what was sent.
  static func withBody(_ request: URLRequest) -> URLRequest {
    guard request.httpBody == nil, let stream = request.httpBodyStream else { return request }
    var copy = request
    var data = Data()
    stream.open()
    defer { stream.close() }
    let bufferSize = 4096
    let buffer = UnsafeMutablePointer<UInt8>.allocate(capacity: bufferSize)
    defer { buffer.deallocate() }
    while stream.hasBytesAvailable {
      let read = stream.read(buffer, maxLength: bufferSize)
      if read <= 0 { break }
      data.append(buffer, count: read)
    }
    copy.httpBody = data
    return copy
  }

  override func startLoading() {
    guard let handler = UnitStubURLProtocol.handler else {
      client?.urlProtocolDidFinishLoading(self)
      return
    }
    var (data, statusCode, headers) = handler(UnitStubURLProtocol.withBody(request))
    if let failBefore = headers.removeValue(forKey: UnitStubURLProtocol.failBeforeResponseHeader) {
      let code: URLError.Code
      switch failBefore {
      case "timedOut": code = .timedOut
      case "secureConnectionFailed": code = .secureConnectionFailed
      default: code = .cannotConnectToHost
      }
      client?.urlProtocol(self, didFailWithError: URLError(code))
      return
    }
    let failWith = headers.removeValue(forKey: UnitStubURLProtocol.failWithHeader)
    guard let requestURL = request.url,
      let response = HTTPURLResponse(
        url: requestURL,
        statusCode: statusCode,
        httpVersion: "HTTP/1.1",
        headerFields: headers
      )
    else {
      client?.urlProtocolDidFinishLoading(self)
      return
    }
    /* URLSession follows a redirect only when the protocol reports it through
     * wasRedirectedTo; a 3xx delivered as a plain response is returned unfollowed.
     * swift-corelibs-foundation traps on wasRedirectedTo, so on Linux the stub
     * never reports one and the redirect-following tests are Darwin-only. */
    #if !os(Linux)
      if (300..<400).contains(statusCode), let location = headers["Location"],
        let redirectURL = URL(string: location, relativeTo: requestURL)?.absoluteURL
      {
        var next = request
        next.url = redirectURL
        client?.urlProtocol(self, wasRedirectedTo: next, redirectResponse: response)
      }
    #endif
    client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
    if failWith == "cannotDecodeContentData" {
      client?.urlProtocol(self, didFailWithError: URLError(.cannotDecodeContentData))
      return
    }
    /* The connection dies, or the deadline passes, after the response
     * headers and part of the body have already arrived. */
    if failWith == "networkConnectionLost" || failWith == "timedOut" {
      client?.urlProtocol(self, didLoad: data.prefix(1))
      let code: URLError.Code = failWith == "timedOut" ? .timedOut : .networkConnectionLost
      client?.urlProtocol(self, didFailWithError: URLError(code))
      return
    }
    client?.urlProtocol(self, didLoad: data)
    client?.urlProtocolDidFinishLoading(self)
  }

  override func stopLoading() {}

}
